using System.Security.Claims; using System.Text.RegularExpressions; using Microsoft.EntityFrameworkCore; using PersonalUltra.Domain; using PersonalUltra.Infrastructure; using PersonalUltra.TrainerApi.Contracts;
namespace PersonalUltra.TrainerApi.Endpoints;
public static class BrandingEndpointExtensions { public static void MapBrandingApi(this WebApplication app){app.MapGet("/api/v1/branding",async(PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{var id=Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);var b=await db.TrainerBrandings.AsNoTracking().SingleAsync(x=>x.TrainerId==id,ct);return Results.Ok(new BrandingResponse(b.DisplayName,b.PrimaryColor??"#FF6A13",b.LogoUrl));}).RequireAuthorization();app.MapPut("/api/v1/branding",async(BrandingRequest r,PersonalUltraDbContext db,ClaimsPrincipal u,HttpContext c,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(r.DisplayName)||!Regex.IsMatch(r.PrimaryColor??"", "^#[0-9A-Fa-f]{6}$"))return c.ApiError("VALIDATION_ERROR","Informe nome e cor hexadecimal válida.",400);var id=Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);var b=await db.TrainerBrandings.SingleAsync(x=>x.TrainerId==id,ct);b.DisplayName=r.DisplayName.Trim();b.PrimaryColor=(r.PrimaryColor ?? "").ToUpperInvariant();b.LogoUrl=string.IsNullOrWhiteSpace(r.LogoUrl)?null:r.LogoUrl.Trim();await db.SaveChangesAsync(ct);return Results.Ok(new BrandingResponse(b.DisplayName,b.PrimaryColor,b.LogoUrl));}).RequireAuthorization();} }

